document.addEventListener("DOMContentLoaded",()=>{"undefined"!=typeof lucide&&lucide.createIcons();const e=document.getElementById("site-header");e&&window.addEventListener("scroll",()=>{window.scrollY>10?e.classList.add("scrolled"):e.classList.remove("scrolled")});const t=document.querySelector(".nav-toggle"),d=document.getElementById("mobile-nav");t&&d&&t.addEventListener("click",()=>{d.classList.contains("open")?(d.classList.remove("open"),t.setAttribute("aria-expanded","false")):(d.classList.add("open"),t.setAttribute("aria-expanded","true"))})});